import { useState } from "react";
import { FaFacebook, FaGoogle, FaTwitter } from "react-icons/fa";

const AuthComponent = () => {
    const [isLogin, setIsLogin] = useState(false);

    return (
        <div className="flex justify-center items-center min-h-screen bg-white">
            <div className=" p-8  w-full max-w-4xl flex flex-col md:flex-row">
                {/* Left Side - Social Login */}
                <div className="w-full md:w-1/2 flex flex-col items-center justify-center p-4">
                    <h2 className="text-2xl font-semibold mb-4">Login with</h2>
                    <div className="flex flex-col gap-4">
                        <button className="flex items-center gap-2 bg-blue-600 text-white px-12 py-2 rounded-md shadow">
                            <FaFacebook size={30} /> Facebook Login
                        </button>
                        <button className="flex items-center gap-2 bg-red-500 text-white px-12 py-2 rounded-md shadow">
                            <FaGoogle size={30}  /> Google Login
                        </button>
                        <button className="flex items-center gap-2 bg-blue-400 text-white px-12 py-2 rounded-md shadow">
                            <FaTwitter size={30}  /> Twitter Login
                        </button>
                    </div>
                </div>

                {/* Right Side - Auth Form */}
                <div className="w-full md:w-1/2 p-4">
                    <h2 className="text-2xl font-semibold mb-4">
                        {isLogin ? "Login" : "Create an Account"}
                    </h2>
                    <form className="flex flex-col gap-4">
                        {!isLogin && (
                            <input
                                type="text"
                                placeholder="Full Name"
                                className="border-b border-gray-400 bg-transparent focus:outline-none p-2"
                            />
                        )}
                        <input
                            type="email"
                            placeholder="Email"
                            className="border-b border-gray-400 bg-transparent focus:outline-none p-2"
                        />
                        <input
                            type="password"
                            placeholder="Password"
                            className="border-b border-gray-400 bg-transparent focus:outline-none p-2"
                        />
                        <div className="w-full">
                            {!isLogin ? (
                                <button className="bg-green-800 text-white px-4 py-3 rounded-md shadow mt-4 w-full">
                                    Create an Account
                                </button>
                            ) : (
                                <div className="flex justify-between items-center mt-4">
                                    <button className="bg-green-800 text-white px-4 py-3 rounded-md shadow">
                                        Login here
                                    </button>
                                    <button className="text-green-800 underline">Forget Password?</button>
                                </div>
                            )}
                        </div>



                    </form>
                    <p className="mt-4 text-center">
                        {isLogin ? "Don't have an account?" : "Already have an account?"}{" "}
                        <button
                            onClick={() => setIsLogin(!isLogin)}
                            className="text-green-800 font-semibold"
                        >
                            {isLogin ? "Sign up here" : "Login here"}
                        </button>
                    </p>
                </div>
            </div>
        </div>
    );
};

export default AuthComponent;