import React, { useState } from "react";

import detailProductImg1 from "../../Assets/product/detialsProduct/detail_05.png";
import detailProductImg3 from "../../Assets/product/detialsProduct/detail_04.jpg";
import detailProductImg2 from "../../Assets/product/detialsProduct/detail_06.jpg";
import detailProductImg4 from "../../Assets/product/detialsProduct/detail_07.jpg";
const SingleProductPage = () => {
  // Static data directly in the component
  const product = {
    name: "Awesome Product",
    description:
      "This is a detailed description of an awesome product that you will love. It's made with care and high-quality materials This is a detailed description of an awesome product that you will love. It's made with care and high-quality materials.",
    price: 29.99,
    quantity: 50,
    image:
      detailProductImg4,
    images: [
      detailProductImg1,
      detailProductImg2,
      detailProductImg3,
      detailProductImg2,
      detailProductImg1,
      detailProductImg4
    ],

    returnPolicy: ["30 days return policy", "Money back guarantee"],
    shipping: ["Free shipping on orders over $50", "Ships within 2-3 business days"],
    rating: 4.5, // Example star rating
  };

  // State for managing the selected image in the slider
  const [selectedImage, setSelectedImage] = useState(product.image);

  // State for dropdowns (Features, Return Policy, Care, Shipping)
  const [dropdowns, setDropdowns] = useState({
    features: false,
    returnPolicy: false,
    careInstructions: false,
    shipping: false,
  });

  // Toggle dropdown visibility
  const toggleDropdown = (section) => {
    setDropdowns((prev) => ({
      ...prev,
      [section]: !prev[section],
    }));
  };
  const [quantity, setQuantity] = useState(1);

  const increaseQuantity = () => setQuantity((prev) => prev + 1);
  const decreaseQuantity = () => setQuantity((prev) => (prev > 1 ? prev - 1 : 1));
  return (
    <div className="max-w-screen-xl mx-auto px-4 py-8">
      {/* Product Information Section */}
      <div className="flex flex-col lg:flex-row items-start gap-12">
        {/* Right Column - Product Details */}

        <div className="lg:w-1/2 flex ">
          {/* Small Images Column */}
          <div className="flex flex-col space-y-2">
            {product.images.map((image, index) => (
              <img
                key={index}
                src={image}
                alt={`product-thumbnail-${index}`}
                className="w-20 h-20 object-cover cursor-pointer border rounded-md"
                onClick={() => setSelectedImage(image)} // Change selected image on click
              />
            ))}
          </div>

          {/* Main Product Image */}
          <div className="ml-4 w-100">
            <img
              src={selectedImage}
              alt={product.name}
              className="w-100 h-100  object-cover rounded-lg border"
            />
          </div>
        </div>

        {/* Left Column - Product Images */}

        <div className="lg:w-1/2">
          {/* Product Name */}
          <h1 className="text-3xl font-semibold text-gray-800">{product.name}</h1>

          {/* Star Rating */}
          <div className="flex items-center mt-2">
            {[...Array(5)].map((_, index) => (
              <svg
                key={index}
                xmlns="http://www.w3.org/2000/svg"
                fill={index < product.rating ? "yellow" : "gray"}
                className="w-5 h-5"
                viewBox="0 0 20 20"
              >
                <path
                  fillRule="evenodd"
                  d="M10 15l-5.878 3.09L5.527 12 1 7.91l6.236-.904L10 1l2.764 5.006 6.236.904-4.527 4.09L15.878 18 10 15z"
                />
              </svg>
            ))}
            <span className="ml-2 text-gray-600">({product.rating})</span>
          </div>

          {/* Product Price */}
          <div className="mt-4 text-2xl font-semibold text-gray-900">${product.price}</div>

          {/* Product Description */}
          <p className="mt-4 mb-4 text-gray-600">{product.description}</p>
          <hr></hr>
          {/* Color Options (Circles) */}
          <div className="mt-4">
            {/* Colors Section */}
            <div className="flex space-x-2 mt-2">
              <span className="font-semibold text-gray-800">Colors:</span>
              <div className="w-6 h-6 rounded-full bg-red-500 cursor-pointer"></div>
              <div className="w-6 h-6 rounded-full bg-blue-500 cursor-pointer"></div>
              <div className="w-6 h-6 rounded-full bg-green-500 cursor-pointer"></div>
              <div className="w-6 h-6 rounded-full bg-gray-500 cursor-pointer"></div>
            </div>

            {/* Sizes Section */}
            <div className="flex space-x-2 mt-4 items-center">
              <span className="font-semibold text-gray-800">Sizes:</span>
              <div className="px-3 py-1 border border-gray-500 rounded cursor-pointer">S</div>
              <div className="px-3 py-1 border border-gray-500 rounded cursor-pointer">M</div>
              <div className="px-3 py-1 border border-gray-500 rounded cursor-pointer">L</div>
              <div className="px-3 py-1 border border-gray-500 rounded cursor-pointer">XL</div>
            </div>
          </div>


          {/* Add to Cart Button */}
          <div className="mt-6 flex items-center space-x-4 ">
            <div className="flex">
              <button
                className="btn btn-outline-secondary me-2 px-3 py-1 border rounded-md hover:bg-gray-100"
                onClick={decreaseQuantity}
              >
                -
              </button>
              <span className="text-4xl font-bold px-2">{quantity}</span>
              <button
                className="btn btn-outline-secondary ms-2 px-3 py-1 border rounded-md hover:bg-gray-100"
                onClick={increaseQuantity}
              >
                +
              </button>
            </div>
            <button className="bg-mycolor  text-white px-6 w-80 py-3 rounded-lg hover:bg-mycolor transition duration-300">
              Add to Cart
            </button>

          </div>



          {/* Return Policy Dropdown */}
          <div className="mt-6">
            <button
              className="w-full text-left font-semibold text-gray-800 py-2 px-4 border rounded-lg bg-gray-100 hover:bg-gray-200 focus:outline-none"
              onClick={() => toggleDropdown("returnPolicy")}
            >
              Return Policy
            </button>
            {dropdowns.returnPolicy && (
              <ul className="mt-2 pl-6 text-gray-600 list-disc">
                {product.returnPolicy.map((policy, index) => (
                  <li key={index}>{policy}</li>
                ))}
              </ul>
            )}
          </div>



          {/* Shipping Dropdown */}
          <div className="mt-6">
            <button
              className="w-full text-left font-semibold text-gray-800 py-2 px-4 border rounded-lg bg-gray-100 hover:bg-gray-200 focus:outline-none"
              onClick={() => toggleDropdown("shipping")}
            >
              Shipping
            </button>
            {dropdowns.shipping && (
              <ul className="mt-2 pl-6 text-gray-600 list-disc">
                {product.shipping.map((shippingInfo, index) => (
                  <li key={index}>{shippingInfo}</li>
                ))}
              </ul>
            )}
          </div>
        </div>

      </div>
    </div>
  );
};

export default SingleProductPage;