import React from "react";
import { BrowserRouter, Routes, Route, Navigate, useLocation , useRoutes  } from "react-router-dom";

import SellerSignup from "../SellerSignUp/SellerSignUp";
import BusinessDetailsForm from "../BusinessDetailsForm/BusinessDetailsForm";
import BusinessInfoForm from "../BusinessInfoForms/BusinessInfoForms";
const SellerBoard = () => {
    let routes = useRoutes([
        { path: "/", element: <SellerSignup /> },
        { path: "/businessform", element: <BusinessDetailsForm /> },
        { path: "/businessinfo", element: <BusinessInfoForm /> }
    ]);

    return (
        <>
           
            {routes}
        </>
    );
}

export default SellerBoard;