import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

import shoe from "../../Assets/products/shoe-1.jpg";
import shoe2 from "../../Assets/products/shoe-2.png";

const Cart = () => {
  const [cartItems, setCartItems] = useState([
    { id: 1, name: "LCD Monitor", price: 850, quantity: 1, image: shoe },
    { id: 2, name: "Hi Gamepad", price: 550, quantity: 2, image: shoe2 },
  ]);

  const handleQuantityChange = (id, value) => {
    const newQuantity = Math.max(1, parseInt(value) || 1);
    setCartItems(cartItems.map((item) => (item.id === id ? { ...item, quantity: newQuantity } : item)));
  };

  const navigate = useNavigate();

  const handleCheckout = () => {
    navigate("/checkout");
  };

  const subtotal = cartItems.reduce((total, item) => total + item.price * item.quantity, 0);

  return (
    <div className="container mx-auto p-4 sm:p-6">
      <div className="text-gray-500 mb-4">Home / Cart</div>

      <div className="bg-white rounded-lg p-4 sm:p-6 shadow-md">
        {/* Responsive Table */}
        <div className="overflow-x-auto">
          <table className="w-full border-collapse">
            <thead>
              <tr className="border-b bg-gray-100">
                <th className="text-left p-2 sm:p-3">Product</th>
                <th className="text-left p-2 sm:p-3">Price</th>
                <th className="text-left p-2 sm:p-3">Quantity</th>
                <th className="text-left p-2 sm:p-3">Subtotal</th>
              </tr>
            </thead>
            <tbody>
              {cartItems.map((item) => (
                <tr key={item.id} className="border-b">
                  <td className="p-2 sm:p-3 flex items-center">
                    <img src={item.image} alt={item.name} className="w-10 h-10 sm:w-12 sm:h-12 mr-3" />
                    {item.name}
                  </td>
                  <td className="p-2 sm:p-3">${item.price}</td>
                  <td className="p-2 sm:p-3">
                    <input
                      type="number"
                      className="w-12 sm:w-16 p-1 border rounded text-center"
                      min="1"
                      value={item.quantity}
                      onChange={(e) => handleQuantityChange(item.id, e.target.value)}
                    />
                  </td>
                  <td className="p-2 sm:p-3">${item.price * item.quantity}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Buttons */}
        <div className="flex flex-col sm:flex-row justify-between items-center mt-6 gap-3">
          <button className="border px-4 py-2 rounded w-full sm:w-auto">Return To Shop</button>
          <button className="border px-4 py-2 rounded w-full sm:w-auto">Update Cart</button>
        </div>

        {/* Coupon & Cart Total */}
        <div className="mt-6 flex flex-col sm:flex-row gap-4">
          {/* Coupon Section */}
          <div className="w-full sm:w-2/3 flex flex-col sm:flex-row gap-2">
            <input type="text" placeholder="Coupon Code" className="border px-4 py-2 rounded w-full md:w-1/2 " />
            <button className="bg-green-700 text-white px-4 py-2 rounded w-full sm:w-auto">Apply Coupon</button>
          </div>
          </div>
          <div className="mt-6 flex flex-col justify-end sm:flex-row gap-4">

          {/* Cart Total Section */}
          <div className="bg-white shadow-lg p-4 sm:p-6 rounded-lg w-full sm:w-1/3">
            <h2 className="text-lg font-semibold mb-3">Cart Total</h2>
            <div className="flex justify-between mb-2">
              <span>Subtotal:</span> <span>${subtotal}</span>
            </div>
            <hr />
            <div className="flex justify-between mt-2 mb-2">
              <span>Shipping:</span> <span>Free</span>
            </div>
            <hr />
            <div className="flex justify-between font-semibold text-lg mt-2">
              <span>Total:</span> <span>${subtotal}</span>
            </div>
            <button
              className="bg-green-700 text-white px-4 py-2 rounded w-full mt-4"
              onClick={handleCheckout}
            >
              Proceed to Checkout
            </button>
          </div>
          </div>
      </div>
    </div>
  );
};

export default Cart;
