import React, { useState } from 'react';
import { FaTrashAlt, FaPlus } from "react-icons/fa";

const Categories = () => {
  const [categories, setCategories] = useState([
    { id: 1, name: "T-Shirts", products: 25, status: "Active" },
    { id: 2, name: "Jeans", products: 18, status: "Inactive" },
    { id: 3, name: "Jackets", products: 12, status: "Active" },
    { id: 4, name: "Hoodies", products: 15, status: "Inactive" },
    { id: 5, name: "Sweaters", products: 20, status: "Active" },
    { id: 6, name: "Dresses", products: 30, status: "Active" },
    { id: 7, name: "Skirts", products: 10, status: "Inactive" },
    { id: 8, name: "Shorts", products: 14, status: "Active" },
    { id: 9, name: "Shoes", products: 22, status: "Active" },
    { id: 10, name: "Bags", products: 16, status: "Inactive" },
    { id: 11, name: "Caps", products: 19, status: "Active" },
    { id: 12, name: "Socks", products: 12, status: "Active" }
]);


  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 5;
  const [showAddModal, setShowAddModal] = useState(false);
  const [newCategory, setNewCategory] = useState("");

  const handleAddCategory = () => {
    if (newCategory.trim() === "") return;
    setCategories([...categories, { id: categories.length + 1, name: newCategory, products: 0, status: "Active" }]);
    setNewCategory("");
    setShowAddModal(false);
  };

  const handleDeleteCategory = (id) => {
    setCategories(categories.filter(category => category.id !== id));
  };

  const totalPages = Math.ceil(categories.length / itemsPerPage);
  const currentPageCategories = categories.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  return (
    <div className="p-6 bg-gray-100 min-h-screen">
      <div className="bg-white shadow-lg rounded-xl p-6 border border-green-700">

        <div className="row mb-4">
          <div className="col-md-9">
            <h2 className="text-2xl font-bold text-green-700">
              <i className="fas fa-box-open mr-2"></i> Categories List
            </h2>
          </div>
          <div className="col-md-3">
            <button onClick={() => setShowAddModal(true)} className='w-100 justify-center flex items-center bg-green-700 text-white px-4 py-2 rounded-lg hover:bg-green-800 transition'>
              <FaPlus className='mr-2' /> Add Category
            </button>
          </div>
        </div>

        <table className='w-full mt-4 bg-white  rounded-lg'>
          <thead className='bg-green-700 text-white'>
            <tr>
              <th className='p-3 text-left'>Name</th>
              <th className='p-3 text-left'>No. of Products</th>
              <th className='p-3 text-left'>Status</th>
              <th className='p-3 text-left'>Actions</th>
            </tr>
          </thead>
          <tbody>
            {currentPageCategories.length < 1 ? (
              <tr>
                <td colSpan='4' className='text-center p-4'>No Categories Found, Please Add Some...</td>
              </tr>
            ) : (
              currentPageCategories.map((category) => (
                <tr key={category.id} className='border-b hover:bg-green-100'>
                  <td className='p-3'>{category.name}</td>
                  <td className='p-3'>{category.products}</td>
                  <td className={`p-3 font-bold ${category.status === "Active" ? "text-green-700" : "text-red-600"}`}>
                    {category.status}
                  </td>
                  <td className='p-3 flex space-x-2'>
                    <button onClick={() => handleDeleteCategory(category.id)} className='bg-green-700 text-white px-3 py-1 rounded hover:bg-green-800 transition'>
                      <FaTrashAlt />
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>

        <div className='flex justify-between mt-3'>
          <button className='bg-green-700 text-white px-3 py-1 rounded hover:bg-green-800 transition' disabled={currentPage === 1} onClick={() => setCurrentPage(currentPage - 1)}>◀  Previous</button>
          {/* <span>{`Page ${currentPage} of ${totalPages}`}</span> */}
          <button className='bg-green-700 text-white px-3 py-1 rounded hover:bg-green-800 transition' disabled={currentPage === totalPages} onClick={() => setCurrentPage(currentPage + 1)}>Next  ▶</button>
        </div>

        {/* Add Category Modal */}
        {showAddModal && (
          <div className='fixed inset-0 flex items-center justify-center bg-black bg-opacity-50'>
            <div className="bg-white rounded-lg shadow-lg w-96">
              <div className="flex justify-between items-center bg-green-700 text-white p-4 rounded-t-lg">
                <h2 className="text-lg font-semibold">Add Category</h2>
                <button onClick={() => setShowAddModal(false)} className="text-white text-xl">&times;</button>
              </div>
              <div className="p-4">
                <label className="block text-gray-700 font-medium mb-2">Category Name</label>
                <input
                  type="text"
                  value={newCategory}
                  onChange={(e) => setNewCategory(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-green-700"
                  placeholder="Enter category name"
                />
              </div>
              <div className="flex justify-end space-x-2 bg-gray-100 p-4 rounded-b-lg">
                <button onClick={() => setShowAddModal(false)} className="px-4 py-2 bg-gray-500 text-white rounded hover:bg-gray-600">Close</button>
                <button onClick={handleAddCategory} className="px-4 py-2 bg-green-700 text-white rounded hover:bg-green-800">
                  Add Category
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Categories;
