import { useState } from "react";
import { FaCcVisa, FaCcMastercard, FaCcPaypal } from "react-icons/fa";
import shoe from "../../Assets/products/shoe-1.jpg";
import shoe2 from "../../Assets/products/shoe-2.png";
const Checkout = () => {
  const [paymentMethod, setPaymentMethod] = useState("cod");

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        {/* Billing Details */}
        <div>
          <h2 className="text-2xl font-semibold mb-6">Billing Details</h2>
          <form className="space-y-4">
            <input
              type="text"
              placeholder="First Name*"
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-gray-500"
            />
            <input
              type="text"
              placeholder="Company Name"
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-gray-500"
            />
            <input
              type="text"
              placeholder="Street Address*"
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-gray-500"
            />
            <input
              type="text"
              placeholder="Apartment, floor, etc. (optional)"
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-gray-500"
            />
            <input
              type="text"
              placeholder="Town/City*"
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-gray-500"
            />
            <input
              type="text"
              placeholder="Phone Number*"
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-gray-500"
            />
            <input
              type="email"
              placeholder="Email Address*"
              className="w-full border rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-gray-500"
            />
            <div className="flex items-center">
              <input type="checkbox" id="save-info" className="mr-2" />
              <label htmlFor="save-info" className="text-sm">
                Save this information for faster check-out next time
              </label>
            </div>
          </form>
        </div>

        {/* Order Summary */}
        <div>
          <div className="border p-6 rounded-lg shadow-md">
            <div className="space-y-4">
              <div className="flex justify-between items-center">
                <div className="flex items-center space-x-3">
                  <img
                    src={shoe}
                    alt="LCD Monitor"
                    className="w-12 h-12"
                  />
                  <span>LCD Monitor</span>
                </div>
                <span className="font-semibold">$650</span>
              </div>

              <div className="flex justify-between items-center">
                <div className="flex items-center space-x-3">
                  <img
                    src={shoe2}
                    alt="Gamepad"
                    className="w-12 h-12"
                  />
                  <span>HI Gamepad</span>
                </div>
                <span className="font-semibold">$1100</span>
              </div>

              <div className="pt-4">
                <div className="flex justify-between mb-3">
                  <span>Subtotal:</span>
                  <span className="font-semibold">$1750</span>
                </div>
                <hr></hr>
                <div className="flex justify-between mb-3 mt-2">
                  <span>Shipping:</span>
                  <span className="font-semibold">Free</span>
                </div>
                <hr></hr>
                <div className="flex justify-between text-lg font-bold">
                  <span>Total:</span>
                  <span>$1750</span>
                </div>
              </div>

              {/* Payment Method */}
              <div className="border-t pt-4 space-y-3">
                <div className="flex items-center space-x-2">
                  <input
                    type="radio"
                    name="payment"
                    value="bank"
                    checked={paymentMethod === "bank"}
                    onChange={() => setPaymentMethod("bank")}
                  />
                  <span>Bank</span>
                  <div className="flex space-x-1 ml-2">
                    <FaCcVisa className="text-black-700 text-xl" />
                    <FaCcMastercard className="text-red-600 text-xl" />
                    <FaCcPaypal className="text-black-700 text-xl" />
                  </div>
                </div>
                <div className="flex items-center space-x-2">
                  <input
                    type="radio"
                    name="payment"
                    value="cod"
                    checked={paymentMethod === "cod"}
                    onChange={() => setPaymentMethod("cod")}
                  />
                  <span>Cash on Delivery</span>
                </div>
              </div>

              {/* Coupon Code */}
              <div className="flex space-x-2 border-t pt-4">
                <input
                  type="text"
                  placeholder="Coupon Code"
                  className="border p-2 rounded-lg w-full focus:outline-none focus:ring-2 focus:ring-gray-500"
                />
                <button className="bg-green-700 text-white px-4 py-2 rounded-lg" style={{textWrap:"nowrap"}}>
                  Apply Coupon
                </button>
              </div>

              {/* Place Order Button */}
              <button className="w-full bg-green-800 text-white py-3 rounded-lg font-semibold mt-4">
                Place Order
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Checkout;
