import React from "react";
import story from "../../Assets/about/story.png"
import team1 from "../../Assets/about/team1.jpg"
import team2 from "../../Assets/about/team2.jpg"
import team3 from "../../Assets/about/team3.jpg"
import { FaFacebookF, FaTwitter, FaInstagram, FaLinkedinIn } from "react-icons/fa";
import OurServices from "../Home/Services";
import { FiPackage, FiUsers, FiSmile, FiThumbsUp } from "react-icons/fi";
import Slider from "react-slick";

const TeamSlider = () => {
    const teamMembers = [
        { name: "Tom Cruise", role: "Executive Advisor" },
        { name: "Emma Watson", role: "Managing Director" },
        { name: "Will Smith", role: "Product Strategist" },
        { name: "Chris Evans", role: "Marketing Head" },
        { name: "Scarlett Johansson", role: "HR Manager" },
        { name: "Robert Downey Jr.", role: "Tech Lead" },
    ];

    const settings = {
        dots: true,
        infinite: true,
        speed: 500,
        slidesToShow: 3,
        slidesToScroll: 1,
        autoplay: true,
        autoplaySpeed: 2000,
        arrows: false,
        responsive: [
            {
                breakpoint: 768, // Mobile screens
                settings: {
                    slidesToShow: 1,
                    slidesToScroll: 1,
                },
            },
            {
                breakpoint: 1024, // Tablets
                settings: {
                    slidesToShow: 2,
                    slidesToScroll: 1,
                },
            },
        ],
    };

    return (
        <div className="mt-10 px-4 bg-white">
            <Slider className="bg-white" {...settings}>
                {teamMembers.map((person, index) => (
                    <div key={index} className="p-4 bg-white">
                        <div className="bg-white shadow-lg rounded-lg text-center">
                            <img src={team1} alt={person.name} className="mx-auto mb-4 " />
                            <h4 className="font-semibold text-lg">{person.name}</h4>
                            <p className="text-gray-500">{person.role}</p>
                            <div className="flex justify-center mt-2 space-x-4 text-lg text-blue-500 pb-4">
                                <FaFacebookF className="cursor-pointer hover:text-gray-400" />
                                <FaTwitter className="cursor-pointer hover:text-gray-400" />
                                <FaInstagram className="cursor-pointer hover:text-gray-400" />
                                <FaLinkedinIn className="cursor-pointer hover:text-gray-400" />
                            </div>
                        </div>
                    </div>
                ))}
            </Slider>
        </div>
    );
};


const AboutUs = () => {

    const stats = [
        { label: "Orders Shipped", value: "10.5k", icon: <FiPackage size={70} /> },
        { label: "Loyalty Members", value: "33k", icon: <FiUsers size={70} />, highlight: true },
        { label: "Satisfied Customers", value: "45.5k", icon: <FiSmile size={70} /> },
        { label: "Positive Reviews", value: "25k", icon: <FiThumbsUp size={70} /> },
    ];
    return (
        <div className="max-w-6xl mx-auto p-6">
            {/* Our Story Section */}
            <div className="grid md:grid-cols-2 gap-6 items-center">
                <div>
                    <h2 className="text-3xl font-bold mb-4">Our Story</h2>
                    <p className="text-gray-600 mb-4">
                        A decade into eCommerce, we've helped over a million customers
                        find what they need. We strive to provide top-quality products and
                        services.
                    </p>
                    <p className="text-gray-600">
                        Join us in revolutionizing the shopping experience with the latest
                        trends and exclusive deals.
                    </p>
                </div>
                <div>
                    <img
                        src={story}
                        alt="Shopping"
                        className="rounded-lg shadow-lg"
                    />
                </div>
            </div>

            <div className="grid md:grid-cols-4 gap-4 mt-10 py-12">
                {stats.map((stat, index) => (
                    <div
                        key={index}
                        className={`p-4 rounded-lg text-center shadow-md flex flex-col items-center ${stat.highlight ? "bg-green-600 text-white" : "bg-gray-100"
                            }`}
                    >
                        <div className="mb-2">{stat.icon}</div>
                        <h3 className="text-xl font-bold">{stat.value}</h3>
                        <p className="text-sm">{stat.label}</p>
                    </div>
                ))}
            </div>

            <TeamSlider />

            <OurServices />
        </div>
    );
};

export default AboutUs;
