import React from "react";
import SellerNavbar from "../SellerNavbar/SellerNavbar";
import SellerSecondNavbar from "../SellerSecondNavbar/SellerSecondNavbar";
import {Link} from "react-router-dom"
export default function SellerSignup() {
    return (
        <>
         <SellerNavbar />
         <SellerSecondNavbar />
        
       
      <div className="flex flex-col items-center justify-center min-h-screen p-6 text-center">
        <h2 className="text-2xl font-bold text-gray-900 md:text-3xl">
          Turn Your Passion into Profit!
        </h2>
        <p className="mt-3 text-gray-600 max-w-lg">
          Join our multi-vendor e-commerce marketplace and reach thousands of customers. Set up your seller account in just a few steps and start selling hassle-free!
        </p>
        <div className="mt-6 flex gap-4">
          <button className="px-5 py-2 border border-gray-700 rounded-md text-gray-700 hover:bg-gray-100 transition">
            Sell as an Individual
          </button>
          <button className="px-5 py-2 bg-green-700 text-white rounded-md hover:bg-green-800 transition">
            <Link to="/seller/businessform"> 
            Sell as a Professional
            </Link>
          </button>
        </div>
      </div>
      </>
    );
  }
  