import React from "react";

export default function ContactForm() {
    return (
      <div className="container mx-auto px-4 py-10">
        <div className="flex flex-col md:flex-row bg-white  p-6 md:p-10">
          {/* Left Section - Contact Info */}
          <div className="w-full md:w-1/3 p-4 border-r border-gray-200 shadow-lg rounded-lg">
            <div className="mb-6">
              <div className="flex items-center space-x-3">
                <div className="bg-green-700 text-white p-3 rounded-full">
                  <i className="fas fa-phone-alt"></i>
                </div>
                <h3 className="text-lg font-semibold">Call To Us</h3>
              </div>
              <p className="text-gray-600 mt-2">
                We are available 24/7, 7 days a week.
              </p>
              <p className="text-gray-800 font-semibold mt-1">
                Phone: +92098568222
              </p>
            </div>
            <hr></hr>
            <div className="mt-3">
              <div className="flex items-center space-x-3">
                <div className="bg-green-700 text-white p-3 rounded-full">
                  <i className="fas fa-envelope"></i>
                </div>
                <h3 className="text-lg font-semibold">Write To Us</h3>
              </div>
              <p className="text-gray-600 mt-2">
                Fill out our form and we will contact you within 24 hours.
              </p>
              <p className="text-gray-800 font-semibold mt-1">
                Email: customer@vendors.com
              </p>
              <p className="text-gray-800 font-semibold">
                Email: support@vendors.com
              </p>
            </div>
          </div>
  
          {/* Right Section - Contact Form */}
          <div className="w-full md:w-2/3 p-4 shadow-lg rounded-lg md:ms-3 ">
            <form className="space-y-4">
              <div className="flex flex-col md:flex-row md:space-x-4">
                <input
                  type="text"
                  placeholder="Your Name *"
                  className="w-full p-3 border rounded-md bg-gray-100"
                />
                <input
                  type="email"
                  placeholder="Your Email *"
                  className="w-full p-3 border rounded-md bg-gray-100"
                />
                <input
                  type="text"
                  placeholder="Your Phone *"
                  className="w-full p-3 border rounded-md bg-gray-100"
                />
              </div>
              <textarea
                placeholder="Your Message"
                className="w-full p-3 border rounded-md h-40 bg-gray-100"
              ></textarea>
             
            </form>
            <div className="flex justify-end mt-3">
            <button className="bg-green-700 text-white px-6 py-3 rounded-md hover:bg-green-700 transition">
                Send Message
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }
  