const BottomProductList = () => {
    return (
        <>
        
        <div className="container flex flex-column  p-4 ">
                <div className="flex">
                    <div className="py-3 px-2 rounded bg-mycolor"> </div>
                    <h6 className="text-xl font-bold ms-3">This Month</h6>
                </div>
                <div className="flex flex-wrap justify-between items-center">
                    <h1 className="text-xl mt-4  fs-1 font-bold">Best Selling Products</h1>
                    <button className="px-5 py-3 mt-3 md:mt-0 bg-mycolor text-white rounded-lg hover:bg-mycolor transition">
                        View All
                    </button>
                </div>

            </div>
        
        
        <div className="container">
            <div className="row">
                {products.map((product, index) => (
                    <div key={product.id} className="col-lg-3 p-3">
                        <div className="bg-transparent p-2 hover:shadow-xl transition position-relative">
                            {/* Product Image */}
                            <div className="position-relative">
                                <img
                                    src={shoe}
                                    alt={product.name}
                                    className="w-100 h-50 object-cover position-relative"
                                />
                                {/* Icons Overlay */}
                                <div className="position-absolute top-0 end-0 d-flex flex-column p-2">
                                    <span className="text-danger bg-white p-2 rounded-circle shadow">
                                        <i className="fas fa-heart"></i>
                                    </span>
                                    <span className="text-dark mt-2 bg-white p-2 mb-2 rounded-circle shadow">
                                        <i className="fas fa-eye"></i>
                                    </span>

                                </div>
                            </div>

                            {/* Product Name */}
                            <h3 className="text-lg font-semibold mt-2">{product.name}</h3>

                            {/* Price Section */}
                            <div className="d-flex gap-3 align-items-center mt-1">
                                <span className="text-success fw-bold">{product.salePrice}</span>
                                <span className="text-muted text-decoration-line-through">{product.price}</span>
                            </div>

                            {/* Rating */}
                            <div className="d-flex align-items-center mt-2">
                                {Array.from({ length: 5 }).map((_, starIndex) => (
                                    <span
                                        key={starIndex}
                                        className={`text-warning ${starIndex < Math.round(product.rating)
                                            ? "fas fa-star"
                                            : "far fa-star"
                                            }`}
                                    />
                                ))}
                                <span className="ms-2 text-muted small">({product.reviews})</span>
                            </div>
                        </div>
                    </div>
                ))}
            </div>
            <hr />
        </div>
        </>
    );
};


export default BottomProductList