import { useState, useEffect } from "react";
import { FiHeart } from "react-icons/fi";  // Unfilled Heart
import { AiOutlineShoppingCart } from "react-icons/ai";  // Unfilled Cart
import { BsShop } from "react-icons/bs";
import { Modal } from 'react-bootstrap';
import 'bootstrap/dist/css/bootstrap.min.css';
import { Link } from 'react-router-dom';
import Logo from "../../Assets/Logo.png"
import logoText from "../../Assets/logo-text.png"
import { useNavigate } from "react-router-dom";
const SellerSecondNavbar = () => {
    const [isDropdownOpen, setDropdownOpen] = useState(false);
    const [showCart, setShowCart] = useState(false);
    const [showModal, setShowModal] = useState(false);
    const [isSignUp, setIsSignUp] = useState(false);
    const [isMobileMenuOpen, setMobileMenuOpen] = useState(false);
    const [isScrolled, setIsScrolled] = useState(false);
    const navigate = useNavigate();

    useEffect(() => {
        const handleScroll = () => {
            setIsScrolled(window.scrollY > 0);
        };

        window.addEventListener("scroll", handleScroll);

        return () => {
            window.removeEventListener("scroll", handleScroll);
        };
    }, []);

    const handleCart = () => {
        navigate("/cart")
    }

    const toggleMobileMenu = () => {
        setMobileMenuOpen(!isMobileMenuOpen);
    };

    return (
        <>
            <nav
                className={`${isScrolled ? "bg-white shadow-md" : "bg-white text-dark fw-bold"
                    } p-4 sticky top-0 z-50 transition-colors duration-300`}
            >
                <div className="container mx-auto flex justify-between items-center ">
                    {/* Mobile Menu Toggle */}
                    <button
                        onClick={toggleMobileMenu}
                        className="lg:hidden text-2xl "
                    >
                        {isMobileMenuOpen ? '✖' : '☰'}
                    </button>

                    {/* Logo or brand name */}
                    <Link to="/" className=" text-lg font-bold">
                        <div className="flex justify-center items-center">
                            Start Selling Ecommerce
                        </div>

                    </Link>

                    {/* Desktop Menu */}
                    <div className="hidden lg:flex justify-center space-x-8">
                        <Link to="/" className=" text-lg hover:text-gray-300"


                        >
                            Benefits
                        </Link>
                        <Link to="/" className=" text-lg hover:text-gray-300">
                            How it works
                        </Link>
                        <Link to="/" className=" text-lg hover:text-gray-300">
                            Pricing
                        </Link>
                        <Link to="/" className=" text-lg hover:text-gray-300">
                            Categories
                        </Link>

                        <Link to="/" className=" text-lg hover:text-gray-300">
                            FAQ
                        </Link>
                    </div>

                    <div className="flex space-x-4">
                        <Link to="/" className=" text-lg hover:text-gray-300">
                            <button className="bg-green-600 text-white rounded-lg p-2 px-3 btn">
                                Start Selling
                            </button>
                        </Link>
                    </div>
                </div>

                {/* Mobile Menu */}
                {isMobileMenuOpen && (
                    <div className="lg:hidden mt-4 space-y-4">
                        <Link to="/" className=" text-lg hover:text-gray-300"


                        >
                            Benefits
                        </Link>
                        <Link to="/" className=" text-lg hover:text-gray-300">
                            How it works
                        </Link>
                        <Link to="/" className=" text-lg hover:text-gray-300">
                            Pricing
                        </Link>
                        <Link to="/" className=" text-lg hover:text-gray-300">
                            Categories
                        </Link>

                        <Link to="/" className=" text-lg hover:text-gray-300">
                            FAQ
                        </Link>


                    </div>
                )}
            </nav>




        </>
    );
};

export default SellerSecondNavbar;
