import React, { useEffect, useState } from "react";
import onedaysale from "../../Assets/bannersale.jpg";

const OneDaySale = () => {
    const [timeLeft, setTimeLeft] = useState(24 * 60 * 60);

    useEffect(() => {
        const timer = setInterval(() => {
            setTimeLeft((prev) => (prev > 0 ? prev - 1 : 0));
        }, 1000);
        return () => clearInterval(timer);
    }, []);

    const formatTime = (seconds) => {
        const hours = Math.floor(seconds / 3600);
        const minutes = Math.floor((seconds % 3600) / 60);
        const secs = seconds % 60;
        return { hours, minutes, secs };
    };

    const { hours, minutes, secs } = formatTime(timeLeft);

    return (
        <div className="relative w-full h-[500px] flex items-center justify-start text-white px-10" style={{
            backgroundImage: `url(${onedaysale})`,
            backgroundSize: "cover",
            backgroundPosition: "center"
        }}>
            <div className=" rounded-lg w-1/2 md:p-8">
                <h6 className="text-xl font-bold mb-4">Categories</h6>
                <h3 className="text-5xl mb-3 ">Enhance Your <br></br> <span className="mt-1">  Music Experience </span></h3>
                
                <div className="flex space-x-4 mt-6">
                    {[{ label: "HRS", value: hours }, { label: "MIN", value: minutes }, { label: "SEC", value: secs }].map((item, index) => (
                        <div key={index} className="flex flex-col items-center">
                            <div className="w-24 h-24 flex flex-column items-center justify-center bg-white text-black text-4xl font-bold rounded-full">
                                {item.value.toString().padStart(2, "0")}
                                <span className=" text-lg font-semibold">{item.label}</span>

                            </div>
                        </div>
                    ))}
                </div>

                <button className="bg-mycolor text-white py-3 mt-5 px-12 rounded-lg text-lg hover:bg-red-700 transition duration-200" style={{textWrap:"nowrap"}}>
                    Buy Now
                </button>
            </div>
        </div>
    );
};

export default OneDaySale;
