import React from "react";
import shoe from "../../Assets/products/shoe-1.jpg";
import shoe2 from "../../Assets/products/shoe-2.png";
import { FiArrowRight } from "react-icons/fi";

const products = [
    {
        id: 1,
        name: "Product 1",
        price: "$50",
        desc: "I am Your Product Please Buy me if you want a good product..",
        image: shoe,
    },
    {
        id: 2,
        name: "Product 2",
        price: "$80",
        desc: "I am Your Product Please Buy me if you want a good product..",
        image: shoe,
    },
    {
        id: 3,
        name: "Product 3",
        price: "$90",
        desc: "I am Your Product Please Buy me if you want a good product..",
        image: shoe2,
    },
    {
        id: 4,
        name: "Product 4",
        price: "$120",
        desc: "I am Your Product Please Buy me if you want a good product..0",
        image: shoe2,
    },
];

const ProductCard = ({ product, className }) => {
    return (
        <div
            className={`relative bg-cover bg-center ${className} rounded-lg overflow-hidden`}
            style={{ backgroundImage: `url(${product.image})` }}
        >
            <div className="absolute inset-0 bg-black/50 flex flex-col justify-end items-start text-white p-4">
                <h3 className="text-lg font-bold">{product.name}</h3>
                <p className="text-sm">
                <span >{product.desc}</span>
                </p>
                <a
                    className="mt-2 inline-flex items-center text-white font-semibold py-2  rounded-lg transition"
                >
                    <span>Shop Now</span>
                    <FiArrowRight className="ml-2" />
                </a>
            </div>
        </div>
    );
};


const NewArrival = () => {
    return (
        <div className="container mx-auto p-4">
            <div className="flex items-center">
                <div className="py-3 px-2 rounded bg-mycolor"></div>
                <h6 className="text-xl font-bold ms-3">Featured</h6>
            </div>
            <div className="flex justify-between items-center">
                <h1 className="text-3xl mt-4 font-bold">New Arrival</h1>
                
            </div>

            {/* Product Layout */}
            <div className="grid md:grid-cols-2 gap-4 mt-6">
                {/* First Column: One Large Product */}
                <ProductCard product={products[0]} className="h-[400px]" />

                {/* Second Column: One Large on Top, Two Small Below */}
                <div className="flex flex-col gap-4">
                    <ProductCard product={products[1]} className="h-[190px]" />
                    <div className="grid grid-cols-2 gap-4">
                        <ProductCard product={products[2]} className="h-[190px]" />
                        <ProductCard product={products[3]} className="h-[190px]" />
                    </div>
                </div>
            </div>
        </div>
    );
};

export default NewArrival;