import React from "react";

const Card = ({ icon, heading, paragraph }) => (
    <div className="mb-3 p-6 hover:shadow-2xl transition-shadow duration-300 ease-in-out transform hover:scale-105">
        <div className="flex flex-col items-center">
            <i className={`${icon} text-white text-4xl bg-gray-800 p-4 rounded-full border border-gray-400`}></i>
            <h5 className="mt-4 text-xl font-semibold text-white-800">{heading}</h5>
            <p className="text-gray-600 text-center mt-2">{paragraph}</p>
        </div>
    </div>
);

const OurServices = () => {
    return (
        <div className="container mt-5">
            <div className="row flex justify-center">
                <div className="col-md-3">
                    <Card
                        icon="fa fa-truck"
                        heading="Free Shipping"
                        paragraph="Enjoy free shipping on all orders!"
                    />
                </div>
                <div className="col-md-3">
                    <Card
                        icon="fa fa-undo"
                        heading="15 Days Return"
                        paragraph="Easy returns within 15 days!"
                    />
                </div>
                <div className="col-md-3">
                    <Card
                        icon="fa fa-credit-card"
                        heading="Flexible Payment"
                        paragraph="Multiple payment options for you."
                    />
                </div>

            </div>
        </div>
    );
};


export default OurServices;