const AllProductsList = () => {
    const navigate = useNavigate();
    return (
        <>
            <div className="container flex justify-between items-center p-4 ">
                <div>
                    <div className="flex">
                        <div className="py-3 px-2 rounded bg-mycolor"> </div>
                        <h6 className="text-xl font-bold ms-3">Our Products</h6>
                    </div>
                    <h1 className="text-xl mt-4 fs-1 font-bold">Explore Our Products</h1>
                </div>
            </div>

            <div className="container">
                <div className="row">
                    {products.map((product, index) => (
                        <div className="col-lg-3" key={product.id} onClick={() => navigate("/productdetails")}  style={{ cursor: "pointer" }}>
                        <ProductCard product={product} />
                      </div>

                    ))}
                </div>

                <div className="container flex flex-col p-4">
                    <div className="flex justify-end items-center">
                        <button className="px-5 py-3 bg-mycolor text-white rounded-lg hover:bg-opacity-90 transition">
                            View All Products
                        </button>
                    </div>
                </div>
                <hr />
            </div>
        </>
    );
};

// ✅ Separate ProductCard Component with State for Hover Effect
const ProductCard = ({ product }) => {
    const [isHovered, setIsHovered] = useState(false);

    return (
        <div
            className=" p-3"
            onMouseEnter={() => setIsHovered(true)}
            onMouseLeave={() => setIsHovered(false)}
        >
            <div className="bg-transparent p-2 transition-all duration-300 relative">
                {/* Product Image */}
                <div className="relative">
                    <img
                        src={shoe}
                        alt={product.name}
                        className="w-full h-50 object-cover"
                    />
                    {/* Icons Overlay */}
                    <div className="absolute top-0 right-0 flex flex-col p-2">
                        <span className="text-red-500 bg-white p-2 rounded-full shadow">
                            <i className="fas fa-heart"></i>
                        </span>
                        <span className="text-gray-800 mt-2 bg-white p-2 mb-2 rounded-full shadow">
                            <i className="fas fa-eye"></i>
                        </span>
                    </div>

                    {/* Add to Cart Button - Show on Hover */}
                    {isHovered && (
                        <div className="absolute bottom-0 left-0 w-full bg-black bg-opacity-60 p-2 text-center transition-all duration-300">
                            <button className="btn btn-black btn-lg w-full text-white">Add to Cart</button>
                        </div>
                    )}
                </div>

                {/* Product Name */}
                <h3 className="text-lg font-semibold mt-2">{product.name}</h3>

                {/* Price Section */}
                <div className="flex gap-3 items-center mt-1">
                    <span className="text-green-500 font-bold">{product.salePrice}</span>
                    <span className="text-gray-400 line-through">{product.price}</span>
                </div>

                {/* Rating */}
                <div className="flex items-center mt-2">
                    {Array.from({ length: 5 }).map((_, starIndex) => (
                        <span
                            key={starIndex}
                            className={`text-yellow-400 ${starIndex < Math.round(product.rating)
                                ? "fas fa-star"
                                : "far fa-star"
                                }`}
                        />
                    ))}
                    <span className="ml-2 text-gray-500 text-sm">({product.reviews})</span>
                </div>
            </div>
        </div>
    );
};



export default AllProductsList;