import React from "react";

import {Link} from "react-router-dom"

import { FaMapMarkerAlt, FaPhoneAlt, FaCreditCard, FaIdCard } from "react-icons/fa";

export default function BusinessDetailsForm() {
    return (
        <div className="flex flex-col   p-6 text-center bg-white container">
            <h2 className="text-2xl font-bold text-gray-900 md:text-3xl">
                Before you begin, please make sure you have the necessary details ready
            </h2>
            <p className="mt-2 text-gray-600">
                Additional information or documents may be requested later.
            </p>

            {/* Icons Section */}
            <div className="mt-6 flex flex-wrap justify-center gap-8">
                <div className="flex flex-col items-center p-5 ">
                    <div className="p-5 border  rounded-lg">
                    <FaMapMarkerAlt className="text-green-700 text-6xl " />
                
                </div>
                    <p className="mt-2 font-medium">Business and contact Address</p>
                
                
                </div>
                <div className="flex flex-col items-center p-5 ">
                    <div className="p-5 border  rounded-lg">
                    <FaPhoneAlt className="text-green-700 text-6xl " />
                
                </div>
                    <p className="mt-2 font-medium">Mobile or Telephone Number</p>
                
                
                </div>

               
                <div className="flex flex-col items-center p-5 ">
                    <div className="p-5 border  rounded-lg">
                    <FaCreditCard className="text-green-700 text-6xl " />
                
                </div>
                    <p className="mt-2 font-medium">Credit Card</p>
                
                
                </div>

                <div className="flex flex-col items-center p-5 ">
                    <div className="p-5 border  rounded-lg">
                    <FaIdCard className="text-green-700 text-6xl"  />
                
                </div>
                    <p  className="mt-2 font-medium" >Identity Details</p>
                
                
                </div>
             
            </div>

            {/* Form Section */}
            <div className="mt-6 w-full  text-left ">
                <label className="block font-medium text-gray-700">Business Location</label>
                <input
                    type="text"
                    className="w-full mt-2 p-3 border rounded-md focus:outline-none focus:ring-2 focus:ring-green-600"
                    readOnly
                />
                <p className="text-sm text-gray-500 mt-1">
                    If you don't own a business, simply enter your country of residence.
                </p>

                <label className="block font-medium text-gray-700 mt-4">Business Type</label>
                <input
                    type="text"
                    placeholder="Enter an entity type"
                    className="w-full mt-2 p-3 border rounded-md focus:outline-none focus:ring-2 focus:ring-green-600"
                />
            </div>

            {/* Policy Section */}
            <div className="mt-6 text-sm text-gray-600 text-left border-b pb-5">
                <p>
                    By selecting "Agree and Continue," you acknowledge and accept the associated policies, agreements, and notices.
                </p>
                <ul className="mt-2 list-disc list-inside">
                    <li>Business Agreement: Applicable in North America, Japan, Europe, Africa, and Pakistan</li>
                    <li>Payment Policies: Supports transactions in UK, UAE, and Pakistani Rupee</li>
                    <li>International Seller Guidelines: Governed by Global Standards</li>
                </ul>
            </div>
            <div className="flex justify-center items-center w-full">
                <button className="w-48 px-6 py-2 mt-12 bg-green-700 text-white rounded-md hover:bg-green-800 transition">
                    <Link to="/seller/businessinfo" >
                    Agree And Continue
                    </Link>
                </button>
            </div>
        </div>
    );
}
