import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

export default function DashBoardSidbar({ onItemClick }) {
  const [isOpen, setIsOpen] = useState(false);
  const [activeItem, setActiveItem] = useState("dashboard");
  const navigate = useNavigate();

  const handleToggle = () => {
    setIsOpen(!isOpen);
  };

  const handleLogout = () => {
    localStorage.removeItem("food123");
    navigate("/admin/login");
  };

  const handleItemClick = (item) => {
    setActiveItem(item);
    onItemClick(item);
    setIsOpen(false); // Close sidebar on mobile after selection
  };

  return (
    <>
      {/* Menu Button */}
      <button
        className="fixed top-4 mt-5 left-4 z-10 bg-green-700 text-white p-3 rounded-lg md:hidden"
        onClick={handleToggle}
      >
        <i className="fas fa-bars text-lg"></i>
      </button>

      {/* Sidebar */}
      <div
        className={`overflow-auto fixed mt-5 top-0 left-0 h-full bg-green-600 text-white shadow-lg transition-transform duration-300 ease-in-out z-40 
        ${isOpen ? "translate-x-0" : "-translate-x-full"} md:translate-x-0 md:w-64`}
      >
        <div className="sidebar-header flex justify-between items-center px-4">
        

          {/* Close Button (Only for mobile) */}
          <button
            className="text-white bg-green-700 rounded p-2 mx-2 hover:bg-green-700 transition-colors md:hidden"
            onClick={handleToggle}
          >
            <i className="fas fa-times"></i>
          </button>
        </div>

        <ul className="list-unstyled px-4 space-y-3">
          {[
            { name: "dashboard", icon: "fa-tachometer-alt", label: "Dashboard" },
            { name: "payments", icon: "fa-credit-card", label: "Payments" },
            { name: "customers", icon: "fa-users", label: "Customers" },
            { name: "orders", icon: "fa-clipboard-list", label: "Orders" },
            { name: "categories", icon: "fa-tags", label: "Categories" },
            { name: "addproducts", icon: "fa-box", label: "Add Product" },
            { name: "products", icon: "fa-box", label: "Products" },
            { name: "settings", icon: "fa-user-cog", label: "Personal Settings" },
          ].map((item) => (
            <li
              key={item.name}
              className={`flex items-center mb-3 rounded-lg p-2 cursor-pointer transition-all duration-300 
                ${activeItem === item.name ? "bg-white text-black" : "text-white  "}`}
              onClick={() => handleItemClick(item.name)}
            >
              <i className={`me-2 fas ${item.icon} text-lg`}></i>
              <span className="text-lg font-medium">{item.label}</span>
            </li>
          ))}
          <li
            className="flex items-center mb-3 cursor-pointer rounded-lg p-2 text-white hover:bg-red-50 hover:text-red-600 transition-all duration-300"
            onClick={handleLogout}
          >
            <i className="me-2 fas fa-sign-out-alt text-lg"></i>
            <span className="text-lg font-medium">Logout</span>
          </li>
        </ul>
      </div>

      {/* Background Overlay for Mobile */}
      {isOpen && (
        <div
          className="fixed inset-0 bg-black bg-opacity-50 z-30 md:hidden"
          onClick={handleToggle}
        ></div>
      )}
    </>
  );
}