function TotalUsersCard() {
  const [users, setUsers] = useState(0);

  useEffect(() => {
    let target = 200;
    let interval = setInterval(() => {
      setUsers(prev => {
        if (prev < target) {
          return Math.min(prev + 1, target);
        } else {
          clearInterval(interval);
          return target;
        }
      });
    }, 50);
  }, []);

  return (
    <div className="card  border-green-700 shadow-lg border-0 ">
      <div className="card-body">
        <h3 className="card-text text-center fw-bolder" style={{ fontWeight: "800" }}>{users}</h3>

        <div className='d-flex justify-content-center'>
          <p className='m-0'>Users This Month</p>
        </div>
      </div>
    </div>
  );
}

