import { useState } from "react";

const BusinessInfoForm = () => {
  const [formData, setFormData] = useState({
    citizenship: "",
    birthCountry: "",
    dob: "",
    verificationMethod: "SMS",
    phoneNumber: "+92-65756-37457",
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  return (
    <div className="max-w-2xl mx-auto p-6 bg-white shadow-md rounded-lg">
      {/* Step Indicator */}
      <div className="flex justify-between items-center mb-6">
        {[1, 2, 3, 4, 5].map((step) => (
          <div key={step} className="flex flex-col items-center">
            <div
              className={`w-10 h-10 flex items-center justify-center rounded-full ${
                step === 1 ? "bg-green-600 text-white" : "bg-gray-300 text-gray-600"
              }`}
            >
              {step}
            </div>
            <p className="text-sm text-gray-600 mt-1">
              {["Individual Information", "Market Places", "Billing", "Store", "Verification"][step - 1]}
            </p>
          </div>
        ))}
      </div>

      <h2 className="text-xl font-semibold mb-4">Personal information for your business</h2>

      {/* Form Fields */}
      <div className="space-y-4">
        <div>
          <label className="block text-gray-700">Country of Citizenship</label>
          <select
            name="citizenship"
            value={formData.citizenship}
            onChange={handleChange}
            className="w-full p-2 border rounded-md"
          >
            <option value="">Select country</option>
            <option value="Pakistan">Pakistan</option>
            <option value="USA">USA</option>
          </select>
        </div>

        <div>
          <label className="block text-gray-700">Country of Birth</label>
          <select
            name="birthCountry"
            value={formData.birthCountry}
            onChange={handleChange}
            className="w-full p-2 border rounded-md"
          >
            <option value="">Select country</option>
            <option value="Pakistan">Pakistan</option>
            <option value="USA">USA</option>
          </select>
        </div>

        <div>
          <label className="block text-gray-700">Date of Birth</label>
          <input
            type="date"
            name="dob"
            value={formData.dob}
            onChange={handleChange}
            className="w-full p-2 border rounded-md"
          />
        </div>

        {/* Verification Method */}
        <div>
          <p className="text-gray-700">Receive pin through</p>
          <div className="flex space-x-4">
            <label className="flex items-center">
              <input
                type="radio"
                name="verificationMethod"
                value="SMS"
                checked={formData.verificationMethod === "SMS"}
                onChange={handleChange}
                className="mr-2"
              />
              SMS
            </label>
            <label className="flex items-center">
              <input
                type="radio"
                name="verificationMethod"
                value="Call"
                checked={formData.verificationMethod === "Call"}
                onChange={handleChange}
                className="mr-2"
              />
              Call
            </label>
          </div>
        </div>

        {/* Phone Number */}
        <div>
          <label className="block text-gray-700">Phone number for Verification</label>
          <div className="flex items-center border rounded-md p-2">
            <span className="mr-2">🇵🇰</span>
            <input
              type="text"
              name="phoneNumber"
              value={formData.phoneNumber}
              onChange={handleChange}
              className="w-full outline-none"
            />
          </div>
          <p className="text-sm text-gray-500">Example: +92-65756-37457</p>
        </div>
      </div>

      {/* Buttons */}
      <div className="flex justify-between mt-6">
        <button className="border border-green-600 text-green-600 px-4 py-2 rounded-md hover:bg-green-100">
          Send SMS
        </button>
        <button className="bg-green-600 text-white px-4 py-2 rounded-md hover:bg-green-700">
          Continue
        </button>
      </div>
    </div>
  );
};

export default BusinessInfoForm;
