import React from "react";
import { BrowserRouter, Routes, Route, Navigate, useLocation } from "react-router-dom";
import Home from "./UserSide/Home/Home.js";
import Footer from "./UserSide/footer.js";
import Navbar from "./UserSide/Navbar.js";
import "./App.css";
import AboutUs from "./UserSide/About/About.js";
import SingleProductPage from "./UserSide/ProductDetails/ProductDetails.js";
import Checkout from "./UserSide/CheckOut/CheckOut.js";
import NotFoundPage from "./UserSide/NotFoundPage.js";
import AuthComponent from "./UserSide/AuthScreen/AuthScreen.js";
import Cart from "./UserSide/Cart/Cart.js";
import WishList from "./UserSide/Wishlist/Wishlist.js";
import ContactForm from "./UserSide/ContactUs/ContactUs.js";
import SellerBoard from "./Seller/SellerBoard/SellerBoard.js";
import Dashboard from "./components/Dashboard/Dashboard.js";
const AppRouter = () => {
    const location = useLocation();
    const isSellerRoute = location.pathname.startsWith("/seller");

    return (
        <>
            {!isSellerRoute && <Navbar />} {/* Hide Navbar for seller routes */}
            <Routes>
                <Route path="/" exact element={<Home />} />
                <Route path="productdetails" exact element={<SingleProductPage />} />
                <Route path="checkout" exact element={<Checkout />} />
                <Route path="/cart" exact element={<Cart />} />
                <Route path="/auth" exact element={<AuthComponent />} />
                <Route path="/about" exact element={<AboutUs />} />
                <Route path="/wishlist" exact element={<WishList />} />
                <Route path="/contact" exact element={<ContactForm />} />
                <Route path="/seller/*" element={<SellerBoard />} />
                <Route path="*" element={<NotFoundPage />} /> {/* 404 Page */}
                <Route
                    path="/seller/dashboard"
                    exact
                    element={ <Dashboard />  }
                />
            </Routes>
            {!isSellerRoute &&  <Footer />}
           
        </>
    );
};

export default AppRouter;
