import React, { useState } from 'react';
import { Modal, Button } from 'react-bootstrap';

export default function Payments() {
    const [show, setShow] = useState(false);
    const [selectedPayment, setSelectedPayment] = useState({});
    const [currentPage, setCurrentPage] = useState(1);
    const [paymentsPerPage] = useState(5);
    const [searchTerm, setSearchTerm] = useState("");

    const handleClose = () => setShow(false);
    const handleShow = (payment) => {
        setSelectedPayment(payment);
        setShow(true);
    };

    const [payments, setPayments] = useState([
        { id: 201, itemName: "Product A", paymentBy: "Stripe", amount: "$120", orderId: "ORD101", orderDate: "2024-12-05" },
        { id: 202, itemName: "Product B", paymentBy: "PayPal", amount: "$150", orderId: "ORD102", orderDate: "2024-12-06" },
        { id: 203, itemName: "Product B", paymentBy: "PayPal", amount: "$150", orderId: "ORD102", orderDate: "2024-12-06" },
        { id: 204, itemName: "Product B", paymentBy: "PayPal", amount: "$150", orderId: "ORD102", orderDate: "2024-12-06" },
        { id: 205, itemName: "Product B", paymentBy: "PayPal", amount: "$150", orderId: "ORD102", orderDate: "2024-12-06" },
        { id: 206, itemName: "Product B", paymentBy: "PayPal", amount: "$150", orderId: "ORD102", orderDate: "2024-12-06" },
        { id: 207, itemName: "Product B", paymentBy: "PayPal", amount: "$150", orderId: "ORD102", orderDate: "2024-12-06" },
        { id: 208, itemName: "Product B", paymentBy: "PayPal", amount: "$150", orderId: "ORD102", orderDate: "2024-12-06" },
        { id: 209, itemName: "Product C", paymentBy: "Bank Transfer", amount: "$200", orderId: "ORD103", orderDate: "2024-12-07" },
    ]);

    const handleDelete = (id) => {
        setPayments(payments.filter(payment => payment.id !== id));
    };

    const handleEdit = (id) => {
        alert(`Edit payment with ID: ${id}`);
    };

    const filteredPayments = payments.filter(payment =>
        payment.itemName.toLowerCase().includes(searchTerm.toLowerCase()) ||
        payment.paymentBy.toLowerCase().includes(searchTerm.toLowerCase()) ||
        payment.orderId.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const indexOfLastPayment = currentPage * paymentsPerPage;
    const indexOfFirstPayment = indexOfLastPayment - paymentsPerPage;



    const currentPayments = filteredPayments.slice(indexOfFirstPayment, indexOfLastPayment);
    const paginate = (pageNumber) => setCurrentPage(pageNumber);

    return (
        <div className="p-6 bg-gray-100 min-h-screen">
            <div className="bg-white shadow-lg rounded-xl p-6 border border-green-700">

                <div className="row mb-4">
                    <div className="col-md-8">
                        <h2 className="text-2xl font-bold text-green-700">
                            <h2 className="text-2xl font-bold text-green-700">💰 Payments List</h2>
                        </h2>
                    </div>
                    <div className="col-md-4">
                        <input
                            type="text"
                            className="border border-green-700 rounded-lg px-4 py-2 w-full md:w-64 focus:outline-none focus:ring-2 focus:ring-green-500"
                            placeholder="🔍 Search payments..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    </div>
                </div>

                <table className="w-full border-collapse mt-4">
                    <thead>
                        <tr className="bg-green-700 text-white">
                            <th className="p-3 text-left">Item Name</th>
                            <th className="p-3 text-left">Payment By</th>
                            <th className="p-3 text-left">Amount</th>
                            <th className="p-3 text-left">Order ID</th>
                            <th className="p-3 text-left">Order Date</th>
                            <th className="p-3 text-left">Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {currentPayments.map((payment) => (
                            <tr key={payment.id} className="border-b">
                                <td className="p-3">{payment.itemName}</td>
                                <td className="p-3">{payment.paymentBy}</td>
                                <td className="p-3">{payment.amount}</td>
                                <td className="p-3">{payment.orderId}</td>
                                <td className="p-3">{payment.orderDate}</td>
                                <td className="text-right p-3">
                                    <i
                                        className="fas fa-edit text-green-700 cursor-pointer mr-3"
                                        onClick={() => handleEdit(payment.id)}
                                    ></i>
                                    <i
                                        className="fas fa-trash text-red-600 cursor-pointer"
                                        onClick={() => handleDelete(payment.id)}
                                    ></i>
                                </td>

                            </tr>
                        ))}
                    </tbody>
                </table>

                {/* Pagination (Previous - Page Numbers - Next) */}
                <div className="flex justify-between mt-4 space-x-2">

                    <button
                        className="bg-green-700 text-white px-5 py-2 rounded-lg shadow-md hover:bg-green-600 disabled:opacity-50"
                        onClick={() => paginate(currentPage - 1)}
                        disabled={currentPage === 1}
                    >
                        ◀ Previous
                    </button>
                    <button
                        className="bg-green-700 text-white px-5 py-2 rounded-lg shadow-md hover:bg-green-600 disabled:opacity-50"
                        onClick={() => paginate(currentPage + 1)}
                        disabled={currentPage >= Math.ceil(filteredPayments.length / paymentsPerPage)}
                    >
                        Next ▶
                    </button>

                </div>
            </div>

            <Modal show={show} onHide={handleClose}>
                <Modal.Header closeButton>
                    <Modal.Title>Payment Details</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    <p><strong>Item Name:</strong> {selectedPayment.itemName}</p>
                    <p><strong>Payment By:</strong> {selectedPayment.paymentBy}</p>
                    <p><strong>Amount:</strong> {selectedPayment.amount}</p>
                    <p><strong>Order ID:</strong> {selectedPayment.orderId}</p>
                    <p><strong>Order Date:</strong> {selectedPayment.orderDate}</p>
                </Modal.Body>
                <Modal.Footer>
                    <Button variant="secondary" onClick={handleClose}>Close</Button>
                </Modal.Footer>
            </Modal>
        </div>
    );
}