import React, { useState, useEffect } from "react";
import { FiArrowRight } from "react-icons/fi";

import OneDaySale from "../OneDaySale/OneDaySale";
import AllProductsList from "./AllProductsList";
import BottomProductList from "./BestSellingProductsList";

import ProductList from "./TrendingProducts";
import NewArrival from "./NewArival";

import slide1 from "../../Assets/homeslider/main-slide-01.jpg"
import slide2 from "../../Assets/homeslider/main-slide-033.jpg"
import slide3 from "../../Assets/homeslider/main-slide-01.jpg"
import slide4 from "../../Assets/homeslider/main-slide-033.jpg"
import OurServices from "./Services";



const FirstSection = () => {
    const categories = ["Electronics", "Fashion", "Home & Living", "Sports", "Toys", "Electronics", "Fashion", "Home & Living", "Sports", "Toys"];

    const slides = [
        { image: slide1, mainHeading: "Latest Electronics", subHeading: "Discover the Future", buttonLink: "/electronics" },
        { image: slide2, mainHeading: "Trendy Fashion", subHeading: "Stay in Style", buttonLink: "/fashion" },
        { image: slide3, mainHeading: "Home & Living", subHeading: "Upgrade Your Space", buttonLink: "/home-living" },
        { image: slide1, mainHeading: "Sports Collection", subHeading: "Gear Up for Victory", buttonLink: "/sports" },
        { image: slide4, mainHeading: "Toys & Games", subHeading: "Fun for Everyone", buttonLink: "/toys" }
    ];

    const [currentIndex, setCurrentIndex] = useState(0);

    useEffect(() => {
        const interval = setInterval(() => {
            setCurrentIndex((prevIndex) => (prevIndex + 1) % slides.length);
        }, 3000); // Change slide every 3 seconds
        return () => clearInterval(interval);
    }, [slides.length]);

    return (
        <div className="grid grid-cols-12 mb-3 md:mb-0  gap-4 md:p-4 md:container" style={{ borderTop: "1px solid #fafafa", borderBottom: "1px solid #fafafa" }}>
            {/* Categories List - Takes 4 parts */}
            <div className="col-span-3 hidden md:block" style={{ borderRight: "1px solid #fafafa" }}>
                <ul className="space-y-2">
                    {categories.map((category, index) => (
                        <li className="font-bold" key={index}>{category}</li>
                    ))}
                </ul>
            </div>

            {/* Image Slider with Dots - Takes 8 parts */}
            <div className=" col-span-12 md:col-span-9   relative w-full ">
                {/* Slider Image with Overlay */}
                <div className="relative w-full ">
                    <img
                        src={slides[currentIndex].image}
                        alt="Slide"
                        className="w-full h-full object-cover rounded-lg shadow-md"
                    />

                    {/* Overlay Content */}
                    <div className="absolute top-8 bottom-0 left-6  text-dark md:p-4 rounded-lg flex flex-col justify-center items-center ">
                        <div> 
                        <p className="text-xl">{slides[currentIndex].subHeading}</p>
                        <h2 className="text-xl md:text-5xl font-bold py-2">{slides[currentIndex].mainHeading}</h2>
                        <a
                            href={slides[currentIndex].buttonLink}
                            className="md:mt-2 mb-2 inline-flex items-center text-dark font-semibold py-2 md:text-2xl rounded-lg transition"
                        >
                            <span>Shop Now</span>
                            <FiArrowRight className="ml-2" />
                        </a>
                        </div>
                    </div>

                </div>

                {/* Dots Indicator */}
                <div className="absolute bottom-4 left-1/2 transform -translate-x-1/2 md:flex space-x-2 hidden ">
                    {slides.map((_, index) => (
                        <div
                            key={index}
                            className={`h-3 w-3 rounded-full ${currentIndex === index ? "bg-blue-600" : "bg-gray-400"} transition-all duration-300`}
                        ></div>
                    ))}
                </div>
            </div>
        </div>
    );
};



// Home Component
const Home = () => {
    return (
        <div>
            <div className="container">
                <FirstSection />
            </div>
            <hr></hr>
            <div className="flex flex-col justify-center items-center"> 
            <ProductList />
            </div>
            <BottomProductList />
            <div className="mt-5 container">
                <OneDaySale />
                <br></br>
                <hr></hr>
            </div>

            <AllProductsList />
            <NewArrival />

            <OurServices />


        </div>
    );
};

export default Home;
