import { useState } from "react";
import shoe from "../../Assets/products/shoe-1.jpg"

const Profile = () => {
  const [user, setUser] = useState({
    image: "",
    name: "Yasir Masood",
    email: "yasir@gmail.com",
    password: "123123",
    address: "Fazaia Housing Scheme, Street 4, D Block",
    city: "Islamabad",
    country: "Pakistan",
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setUser({ ...user, [name]: value });
  };

  return (
<div className="bg-white  p-6  border-green-700">  
        <div className="w-full  p-8 bg-white rounded-xl shadow-lg">
        <h2 className="text-3xl font-semibold text-center text-green-700 mb-6">
          Profile Settings
        </h2>

        {/* Profile Image */}
        <div className="flex justify-center mb-6">
          <label htmlFor="imageUpload" className="cursor-pointer">
            <img
              src={user.image || shoe}
              alt="Profile"
              className="w-28 h-28 rounded-full border-4 border-green-700 shadow-md object-cover"
            />
          </label>
          <input
            type="file"
            id="imageUpload"
            className="hidden"
            onChange={(e) => {
              const file = e.target.files[0];
              if (file) {
                const reader = new FileReader();
                reader.onloadend = () => setUser({ ...user, image: reader.result });
                reader.readAsDataURL(file);
              }
            }}
          />
        </div>

        {/* Input Fields */}
        <div className="grid grid-cols-2 gap-6">
          {[
            { name: "name", label: "Full Name" },
            { name: "email", label: "Email Address" },
            { name: "password", label: "Password" },
            { name: "address", label: "Address" },
            { name: "city", label: "City" },
            { name: "country", label: "Country" },
          ].map(({ name, label }) => (
            <div key={name} className="flex flex-col">
              <label className="text-gray-700 font-medium mb-1">
                {label}
              </label>
              <input
                type={name === "password" ? "password" : "text"}
                name={name}
                value={user[name]}
                onChange={handleChange}
                className="w-full p-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500"
              />
            </div>
          ))}
        </div>

        {/* Update Button */}
        <div className="flex justify-start mt-6">
          <button className="px-6 py-3 bg-green-700 hover:bg-green-800 transition-all text-white font-bold rounded-lg shadow-md">
            Save Changes
          </button>
        </div>
      </div>
    </div>
  );
};

export default Profile;