import React, { useState } from "react";
import { Modal, Button, Form } from "react-bootstrap";

export default function Customers() {
  const [show, setShow] = useState(false);
  const [selectedCustomer, setSelectedCustomer] = useState({});
  const [currentPage, setCurrentPage] = useState(1);
  const [customersPerPage] = useState(5);
  const [searchTerm, setSearchTerm] = useState("");

  const handleClose = () => setShow(false);
  const handleShow = (customer) => {
    setSelectedCustomer(customer);
    setShow(true);
  };

  const [customers, setCustomers] = useState([
    { id: 101, name: "John Doe", email: "john@example.com", phone: "123-456-7890", address: "New York, USA", joinedDate: "2024-01-05" },
    { id: 102, name: "Jane Smith", email: "jane@example.com", phone: "987-654-3210", address: "Los Angeles, USA", joinedDate: "2024-02-10" },
    { id: 103, name: "Alice Johnson", email: "alice@example.com", phone: "555-666-7777", address: "Chicago, USA", joinedDate: "2024-03-15" },
    { id: 104, name: "Bob Brown", email: "bob@example.com", phone: "111-222-3333", address: "Houston, USA", joinedDate: "2024-04-20" },
    { id: 105, name: "Charlie White", email: "charlie@example.com", phone: "444-555-6666", address: "Phoenix, USA", joinedDate: "2024-05-25" },
    { id: 106, name: "David Green", email: "david@example.com", phone: "777-888-9999", address: "Miami, USA", joinedDate: "2024-06-30" },
  ]);

  const handleDelete = (id) => {
    setCustomers(customers.filter((customer) => customer.id !== id));
  };

  const handleEditChange = (e) => {
    const { name, value } = e.target;
    setSelectedCustomer({ ...selectedCustomer, [name]: value });
  };

  const handleSave = () => {
    setCustomers(customers.map((customer) =>
      customer.id === selectedCustomer.id ? selectedCustomer : customer
    ));
    setShow(false);
  };

  const filteredCustomers = customers.filter((customer) =>
    customer.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    customer.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    customer.phone.includes(searchTerm)
  );

  const indexOfLastCustomer = currentPage * customersPerPage;
  const indexOfFirstCustomer = indexOfLastCustomer - customersPerPage;
  const currentCustomers = filteredCustomers.slice(indexOfFirstCustomer, indexOfLastCustomer);

  const paginate = (pageNumber) => setCurrentPage(pageNumber);

  return (
    <div className="p-6 bg-gray-100 min-h-screen">
      <div className="bg-white shadow-lg rounded-xl p-6 border border-green-700">
        <div className="row mb-4">
          <div className="col-md-8">
            <h2 className="text-2xl font-bold text-green-700">👥 Customers List</h2>
          </div>
          <div className="col-md-4">
            <input
              type="text"
              className="border border-green-700 rounded-lg px-4 py-2 w-full md:w-64 focus:outline-none focus:ring-2 focus:ring-blue-500"
              placeholder="🔍 Search customers..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>

        <table className="w-full border-collapse mt-4">
          <thead>
            <tr className="bg-green-700 text-white">
              <th className="p-3 text-left">Name</th>
              <th className="p-3 text-left">Email</th>
              <th className="p-3 text-left">Phone</th>
              <th className="p-3 text-left">Address</th>
              <th className="p-3 text-left">Joined Date</th>
              <th className="p-3 text-left">Actions</th>
            </tr>
          </thead>
          <tbody>
            {currentCustomers.map((customer) => (
              <tr key={customer.id} className="border-b">
                <td className="p-3">{customer.name}</td>
                <td className="p-3">{customer.email}</td>
                <td className="p-3">{customer.phone}</td>
                <td className="p-3">{customer.address}</td>
                <td className="p-3">{customer.joinedDate}</td>
                <td className="text-right p-3">
                  <i className="fas fa-eye text-green-700 cursor-pointer mr-3" onClick={() => handleShow(customer)}></i>
                  <i className="fas fa-edit text-blue-700 cursor-pointer mr-3" onClick={() => handleShow(customer)}></i>
                  <i className="fas fa-trash text-red-600 cursor-pointer" onClick={() => handleDelete(customer.id)}></i>
                </td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* Pagination */}
        <div className="flex justify-between mt-4 space-x-2">
          <button
            className="bg-green-700 text-white px-5 py-2 rounded-lg shadow-md hover:bg-green-700 disabled:opacity-50"
            onClick={() => paginate(currentPage - 1)}
            disabled={currentPage === 1}
          >
            ◀ Previous
          </button>
          <button
            className="bg-green-700 text-white px-5 py-2 rounded-lg shadow-md hover:bg-green-700 disabled:opacity-50"
            onClick={() => paginate(currentPage + 1)}
            disabled={currentPage >= Math.ceil(filteredCustomers.length / customersPerPage)}
          >
            Next ▶
          </button>
        </div>
      </div>

      {/* Modal for Editing Customer */}
      <Modal show={show} onHide={handleClose} centered>
        <Modal.Header closeButton>
          <Modal.Title>Edit Customer</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form>
            <Form.Group className="mb-3">
              <Form.Label>Name</Form.Label>
              <Form.Control
                type="text"
                name="name"
                value={selectedCustomer.name || ""}
                onChange={handleEditChange}
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Email</Form.Label>
              <Form.Control
                type="email"
                name="email"
                value={selectedCustomer.email || ""}
                onChange={handleEditChange}
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Phone</Form.Label>
              <Form.Control
                type="text"
                name="phone"
                value={selectedCustomer.phone || ""}
                onChange={handleEditChange}
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Address</Form.Label>
              <Form.Control
                type="text"
                name="address"
                value={selectedCustomer.address || ""}
                onChange={handleEditChange}
              />
            </Form.Group>
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleClose}>
            Cancel
          </Button>
          <Button variant="success" onClick={handleSave}>
            Save Changes
          </Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
}